-- GENERATED by `wfj generate` from data/gossip/gossip-ae.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ae04a23ef5abffc7"] = { "Puoi andare a dire a Stoutmantle che è qui che si nasconde la banda dei Defias, {name}.", "." },
  ["ae05f38f19e756fc"] = { "{name}, eh? Ehi! <Cittadino/Cittadina> {name}, vieni qua. Il gran signore Bolvar Domadraghi ha chiesto che tutti gli eroi abili dell'⟦Alliance=Alleanza⟧ si presentino da lui al Castello di ⟦Stormwind=Roccavento⟧. Sei <stato/stata> appena <reclutato/reclutata>, <amico/amica>! Muoviti!", "." },
  ["ae0bdfc7d7cb693f"] = { "Le nostre carovane partono più o meno due volte al giorno, ma accidenti se il Flagello non ce la mette tutta per impedire a Didier e ai suoi muli di portare i carichi al fronte. La cosa più folle che abbia mai visto. Se solo avessimo qualche avventuriero eroico per proteggere i carichi...", "." },
  ["ae1486383c420cd1"] = { "Il peggio deve ancora venire, {race}.", "." },
  ["ae2e8664bb495092"] = { "Ciao, ⟦Jubjub=Pincopalla⟧. Mi sei mancato!", "." },
  ["ae3905f7702e864d"] = { "%s inizia a lanciare un incantesimo su ⟦Grimclaw=Truceartiglio⟧.", "." },
  ["ae3b5a1ed12a14c2"] = { "Vicino al ⟦Crystal Lake=Lago di Cristallo⟧ vive una signora di nome Adele Fielder. Fa toppe per le guardie del posto con il cuoio che le avanza e che riceve dalla scuoiatrice della zona, Helene. Probabilmente è lei la persona da cercare, se ti interessa imparare la professione.", "." },
  ["ae3bfd52a7ef8962"] = { "Ah, {name}! Sei proprio la persona che speravo di vedere! Abbiamo abbastanza rifornimenti per lanciare un assalto di terra contro l'⟦Horde=Orda⟧! Il primo maresciallo Teravaine aspetta ordini nel ⟦Field of Strife=Pian della Discordia⟧...\n\nSei <un/una> <veterano/veterana> <coraggioso/coraggiosa> che ha dato prova di sé più e più volte. Vuoi consegnare gli ordini a Teravaine?", "." },
  ["ae3dbd56335ce9dc"] = { "Hai sprecato il tuo tempo e il mio venendo da me per l'addestramento, {name}. Non ho tempo per insegnare le basi. Qui combattiamo una guerra, e questa è una delle linee del fronte. Non tornare da me finché non sarai più <preparato/preparata>.", "." },
  ["ae4845faa87b84ac"] = { "Credete di aver vinto, vermi, ma contro la potenza del Flagello non c'è vittoria per i vivi! Non vi siete liberati di noi!", "." },
  ["ae487ad9cd93f824"] = { "Il mio tormento è finito e ora posso raggiungere la Dea. Grazie infinite!", "." },
  ["ae5613f0b40d386f"] = { "Le fattorie vanno liberate. ⟦Stormwind=Roccavento⟧ avrà anche abbandonato questa gente, ma che mi venga un accidente se lo farò anch'io.", "." },
  ["ae5f41235021794c"] = { "Ladro", "." },
  ["ae6169dd31fde556"] = { "Hai dei rivestimenti di mithril?", "." },
  ["ae65abe2d9f739d2"] = { "Mentre esamini la gabbia e l'elfa della notte al suo interno, provi uno strano senso di déjà vu. Per qualche motivo non incrocia il tuo sguardo: è quasi come se per lei tu non fossi lì.", "." },
  ["ae66532f6181cc4c"] = { "Ehi, Stone, hai sentito della nuova macchina a vapore su cui sta lavorando il vecchio Tonkrend?", "." },
  ["ae6d0ffacbfce30f"] = { "La vita del fabbro non è facile, ma ti mette l'acciaio nelle ossa e il fuoco nel cuore. Mio padre era fabbro, e prima di lui mio nonno, nelle forge sotto Grim Batol. E ora mio figlio segue le nostre orme: quel ragazzo è il mio orgoglio.", "." },
  ["ae6d6f28e50adb1d"] = { "Chi ha evocato Aman?", "." },
  ["ae750710cc2338f9"] = { "Disonoriamo i nostri antenati. Disonoriamo coloro che abbiamo perduto... perdonami, Reginald.", "." },
  ["ae76e4fdd8802829"] = { "Salute, {class}. Il tempo e il bere hanno offuscato i miei sensi esteriori, ma i miei occhi interiori restano forti.", "." },
  ["ae77ba6abee8c96b"] = { "Throm'ka, {class} dell'⟦Horde=Orda⟧, a testa alta! Sono il signore della guerra Gorchuk, comandante dello sforzo bellico dell'⟦Horde=Orda⟧. Ci attendono tempi difficili, ma prevarremo, come sempre.\n\nSe hai domande, falle pure.", "." },
  ["ae8a38c645628e69"] = { "La vostra base è perduta, mortali! Dalle sue ceneri sorgerà la vita!", "." },
  ["ae8aa4a468cc9f4d"] = { "Luce, dammi la forza!", "." },
  ["ae924ce29bbfc50e"] = { "Non possiamo occuparci da soli di tutte le minacce di questa zona. Ci farebbe comodo un'altra mano per combattere, {name}.", "." },
  ["ae94e081ac11ecc0"] = { "Qui siamo parecchio lontani da tutto ciò che chiamerei civiltà, almeno finché l'⟦Horde=Orda⟧ non potrà mandarci altri rinforzi. Ti deve proprio piacere lavorare il cuoio.", "." },
  ["ae981e63948b1956"] = { "Una voce tonante rimbomba dalla pietra...\n\nChe cos'è questo? Sento un piccolo cultista che zampetta qua intorno! Fila via, parassita, o affronta l'ira dei signori del Concilio!", "." },
  ["aeaf020f23181f41"] = { "Sì, {class}? Sei qui a fare rapporto?", "." },
  ["aeb495a6b903187f"] = { "Dammene un altro, Langston.", "." },
  ["aeb9962bed7dbaba"] = { "Non perderti tutte le meraviglie e le attrazioni della ⟦Darkmoon Faire=Fiera di Lunacupa⟧ quando arriverà in città!", "." },
  ["aebeff36f8230e21"] = { "Ci chiamavano Thrall's Grasp: venti dei soldati più abili e onorati di Thrall.\n\nAvevo ordinato al reggimento di costruire un accampamento qui, al confine delle ⟦Blasted Lands=Terre Devastate⟧, mentre aspettavamo che arrivassero gli ordini da Orgrimmar. Passarono settimane senza notizie dal Capoguerra; gli uomini diventavano irrequieti.\n\nFu una decisione da prendere sul momento, {name}. Ero giovane, pieno di ambizione e senza paura di nulla. Il battaglione si sarebbe avventurato nelle ⟦Blasted Lands=Terre Devastate⟧ sotto il mio comando.\n\nUna decisione che avrei rimpianto.", "." },
  ["aec8f595a0acd13c"] = { "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "." },
  ["aece2f49d5584b76"] = { "Mmm... sì, ho una ricetta che potrebbe esserti utile. Lascia che te la insegni!", "." },
  ["aed0a54bb5658151"] = { "In vita ho dedicato le mie energie a guarire gli altri. Vediamo ora, nella morte, quanto dolore posso causare!", "." },
  ["aed26b0faff2971e"] = { "Mmmh...", "." },
  ["aed393389edc4f50"] = { "È fatta. La Fiamma Eterna arde di nuovo.\n\nLa tua prova è completa. Sono lieto di consegnarti il tuo ⟦Fire Totem=Totem del Fuoco⟧. Usa bene questo simbolo di potere nei tuoi viaggi, {name}.\n\nRicorda solo che il potere del piano elementale serve chi lo rispetta e consuma chi non lo fa. Questa è la nostra via.", "." },
  ["aed93e2e0d387838"] = { "Riuscii a malapena a fingere la morte mentre i cadaveri del Flagello mi si ammucchiavano addosso. C'erano solo il buio e i suoni attutiti della battaglia sopra di me. Il cozzare del ferro, il digrignare e lo stridere... suoni orribili, terribili. E poi calò il silenzio. Mi chiamò! \"Fairbanks! Fairbanks, dove sei? Parlami, Fairbanks!\" E poi venne il suono dell'incredulità. Il morso del tradimento, {race}...", "." },
  ["aedcb130117e9754"] = { "Dov'è l'anziano Scruta Cieli?", "." },
  ["aede8afc27a36bd2"] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ colpirà i malvagi e scaccerà il male da queste terre!", "." },
  ["aee0b2082422c2ca"] = { "Mette la pietra nella buca!", "." },
  ["aef203e9c9f78c68"] = { "Il padrone mi vendicherà!!", "." },
  ["aef86d4867a7699a"] = { "Onorare gli anziani significa onorare la propria cultura e il proprio popolo, {class}. Per questo le Monete degli Avi sono un modo concreto per riconoscere chi sceglie di seguire una venerabile via di rispetto.\n\nDurante questa Celebrazione della Luna potrai avere l'occasione di onorare molti anziani. Così facendo otterrai le Monete degli Avi. Portami queste monete e ricompenserò la tua diligenza con una scelta di oggetti unici.", "." },
  ["aefaa283c13fc9ac"] = { "Ora io schiacciare te con mie mani!", "." },
  ["aefc21c5525a4193"] = { "Fammi vedere i tuoi piatti della festa.", "." },
  ["aefdeec6b7464496"] = { "Li hai visti? Gli skycutter hanno ripreso a volare! Però ho sentito che non abbiamo ancora contatti con le altre isole shen'dorei.\r\n\nSpero che ristabiliremo presto i contatti con Shen'dramar ed Eldranaar... sempre che esistano ancora.", "." },
})
